109	// remotes is the set of already-configured remote names and currentURL the
110	// URL of the target remote ("" when it does not exist).
111	//
112	// upstream is the requested preserve-under name; it is honored only when the
113	// target remote is actually being repointed and the name is free. An occupied
114	// name is skipped rather than clobbered — the replaced URL is echoed either way,
115	// so nothing is lost, and silently rewriting an existing `upstream` would be the
116	// one genuinely destructive thing this command could do.
117	func planMirrorRemote(remote, mirrorURL, currentURL, upstream string, remotes map[string]bool) mirrorRemotePlan {
118		plan := mirrorRemotePlan{remote: remote, mirrorURL: mirrorURL}
119		if !remotes[remote] {
120			plan.add = true
121			return plan
122		}
123		if strings.EqualFold(strings.TrimSpace(currentURL), mirrorURL) {
124			plan.noop = true
125			return plan
126		}
127		plan.replacedURL = currentURL
128		if upstream != "" && upstream != remote && !remotes[upstream] {
129			plan.preserveAs = upstream
130		}
131		return plan
132	}
