134	// applyMirrorRemotePlan performs the plan's git-config writes. The preserve step
135	// runs first so a failure there aborts before the original URL is overwritten.
136	func applyMirrorRemotePlan(ctx context.Context, dir string, plan mirrorRemotePlan) error {
137		if plan.noop {
138			return nil
139		}
140		if plan.preserveAs != "" {
141			if _, err := gitRunner(ctx, dir, "remote", "add", plan.preserveAs, plan.replacedURL); err != nil {
142				return fmt.Errorf("preserve current %s URL as %q: %w", plan.remote, plan.preserveAs, err)
143			}
144		}
145		verb := "set-url"
146		if plan.add {
147			verb = "add"
148		}
149		if _, err := gitRunner(ctx, dir, "remote", verb, plan.remote, plan.mirrorURL); err != nil {
150			return fmt.Errorf("point remote %q at the mirror: %w", plan.remote, err)
151		}
152		return nil
153	}
